import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/FLIP.md","filePath":"manual-en/FLIP.md","lastUpdated":1785684581000}'),s={name:"manual-en/FLIP.md"};function o(i,t,n,c,h,l){return e(),a("div",null,[...t[0]||(t[0]=[r(`<h3 id="_12-5-flip" tabindex="-1">12.5 FLIP <a class="header-anchor" href="#_12-5-flip" aria-label="Permalink to &quot;12.5 FLIP&quot;">​</a></h3><pre><code>FLIP /VARIABLES=var_list /NEWNAMES=var_name.
</code></pre><p><code>FLIP</code> transposes rows and columns in the active dataset. It causes cases to be swapped with variables, and vice versa.</p><p>All variables in the transposed active dataset are numeric. String variables take on the system-missing value in the transposed file.</p><p><code>N</code> subcommands are required. If specified, the <code>VARIABLES</code> subcommand selects variables to be transformed into cases, and variables not specified are discarded. If the <code>VARIABLES</code> subcommand is omitted, all variables are selected for transposition.</p><p>The variables specified by <code>NEWNAMES</code>, which must be a string variable, is used to give names to the variables created by <code>FLIP</code>. Only the first 8 characters of the variable are used. If <code>NEWNAMES</code> is not specified then the default is a variable named <strong>CASE_LBL</strong> , if it exists. If it does not then the variables created by <code>FLIP</code> are named VAR000 through VAR999, then VAR1000, VAR1001, and so on.</p><p>When a <code>NEWNAMES</code> variable is available, the names must be canonicalized before becoming variable names. Invalid characters are replaced by letter ‘V’ in the first position, or by ‘_’ in subsequent positions. If the name thus generated is not unique, then numeric extensions are added, starting with 1, until a unique name is found or there are no remaining possibilities. If the latter occurs then the <code>FLIP</code> operation aborts.</p><p>The resultant dictionary contains a <strong>CASE_LBL</strong> variable, a string variable of width 8, which stores the names of the variables in the dictionary before the transposition. Variables names longer than 8 characters are truncated. If <code>FLIP</code> is called again on this dataset, the <strong>CASE_LBL</strong> variable can be passed to the <code>NEWNAMES</code> subcommand to recreate the original variable names.</p><p><code>FLIP</code> honors <code>N OF CASES</code> (see <a href="./N-OF-CASES">N OF CASES</a>). It ignores <code>TEMPORARY</code> (see <a href="./TEMPORARY">TEMPORARY</a>), so that “temporary” transformations become permanent.</p><h4 id="_12-5-1-flip-examples" tabindex="-1">12.5.1 Flip Examples <a class="header-anchor" href="#_12-5-1-flip-examples" aria-label="Permalink to &quot;12.5.1 Flip Examples&quot;">​</a></h4><p>In Example 12.5, data has been entered using <code>DATA LIST</code> (see <a href="./DATA-LIST">DATA LIST</a>) such that the first variable in the dataset is a string variable containing a description of the other data for the case. Clearly this is not a convenient arrangement for performing statistical analyses, so it would have been better to think a little more carefully about how the data should have been arranged. However often the data is provided by some third party source, and you have no control over the form. Fortunately, we can use <code>FLIP</code> to exchange the variables and cases in the active dataset.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data list notable list /heading (a16) v1 v2 v3 v4 v5 v6 begin data. date-of-birth 1970 1989 2001 1966 1976 1982 sex 1 0 0 1 0 1 score 10 10 9 3 8 9 end data.  echo &#39;Before FLIP:&#39;. display variables. list.  flip /variables = all /newnames = heading.  echo &#39;After FLIP:&#39;. display variables. list.</span></span></code></pre></div><p><strong>Example 12.5:</strong> Using <code>FLIP</code> to exchange variables and cases in a dataset</p><p>As you can see in Results 12.3 before the <code>FLIP</code> command has run there are seven variables (six containing data and one for the heading) and three cases. Afterwards there are four variables (one per case, plus the <strong>CASE_LBL</strong> variable) and six cases. You can delete the <strong>CASE_LBL</strong> variable (see <a href="./DELETE-VARIABLES">DELETE VARIABLES</a>) if you don’t need it.</p><table tabindex="0"><thead><tr><th>heading</th><th>v1</th><th>v2</th><th>v3</th><th>v4</th><th>v5</th><th>v6</th></tr></thead><tbody><tr><td>Name</td><td>Position</td><td>Print Format</td><td>Write Format</td><td></td><td></td><td></td></tr><tr><td>heading</td><td>1</td><td>A16</td><td>A16</td><td></td><td></td><td></td></tr><tr><td>v1</td><td>2</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>v2</td><td>3</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>v3</td><td>4</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>v4</td><td>5</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>v5</td><td>6</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>v6</td><td>7</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>date-of-birth</td><td>1970.00</td><td>1989.00</td><td>2001.00</td><td>1966.00</td><td>1976.00</td><td>1982.00</td></tr><tr><td>sex</td><td>1.00</td><td>.00</td><td>.00</td><td>1.00</td><td>.00</td><td>1.00</td></tr><tr><td>score</td><td>10.00</td><td>10.00</td><td>9.00</td><td>3.00</td><td>8.00</td><td>9.00</td></tr><tr><td>Name</td><td>Position</td><td>Print Format</td><td>Write Format</td><td></td><td></td><td></td></tr><tr><td>CASE_LBL</td><td>1</td><td>A8</td><td>A8</td><td></td><td></td><td></td></tr><tr><td>date_of_birth</td><td>2</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>sex</td><td>3</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>score</td><td>4</td><td>F8.2</td><td>F8.2</td><td></td><td></td><td></td></tr><tr><td>CASE_LBL</td><td>date_of_birth</td><td>sex</td><td>score</td><td></td><td></td><td></td></tr><tr><td>v1</td><td>1970.00</td><td>1.00</td><td>10.00</td><td></td><td></td><td></td></tr><tr><td>v2</td><td>1989.00</td><td>.00</td><td>10.00</td><td></td><td></td><td></td></tr><tr><td>v3</td><td>2001.00</td><td>.00</td><td>9.00</td><td></td><td></td><td></td></tr><tr><td>v4</td><td>1966.00</td><td>1.00</td><td>3.00</td><td></td><td></td><td></td></tr><tr><td>v5</td><td>1976.00</td><td>.00</td><td>8.00</td><td></td><td></td><td></td></tr><tr><td>v6</td><td>1982.00</td><td>1.00</td><td>9.00</td><td></td><td></td><td></td></tr></tbody></table><p><strong>Results 12.3:</strong> The results of using <code>FLIP</code> to exchange variables and cases in a dataset</p>`,16)])])}const v=d(s,[["render",o]]);export{b as __pageData,v as default};
